"""Parsing tickets from text."""
from tickets import Ticket


def _parse_line(line):
    team, hours = line.split(",")
    return Ticket(team.strip(), int(hours))


def parse_tickets(text):
    """Parse lines of 'team,hours' into Ticket records. Blank lines are skipped."""
    out = []
    line = ""
    for ch in text:
        if ch == "\n":
            if line.strip():
                out.append(_parse_line(line))
            line = ""
        else:
            line += ch
    return out

